        try jw.objectField("applied_lsn");
        try jw.write(self.applied_lsn);
        if (self.safe_read_lsn) |value| {
            try jw.objectField("safe_read_lsn");
            try jw.write(value);
        }
        try jw.endObject();
    }
};

